async function piPersistBookingHotelIds(linked) {
  if (!pool || !linked || !linked.length) return 0;
  try {
    const r = await pool.query("SELECT data FROM app_data WHERE key='main'");
    if (!r.rows.length) return 0;
    const data = r.rows[0].data || {};
    const applied = piBooking.applyBookingHotelIds(data.apts || [], linked);
    if (!applied.updated) return 0;
    data.apts = applied.apts;
    await pool.query("UPDATE app_data SET data=$1, updated_at=NOW() WHERE key='main'", [data]);
    return applied.updated;
  } catch (ePersist) {
    console.error('[platform-invoices] persist bookingHotelId', ePersist.message);
    return 0;
  }
}
