async function piBookingStorageStateForMap() {
  const row = await piLoadPortalSession('booking');
  if (row && row.storageState) return row.storageState;
  const raw = process.env.BOOKING_STORAGE_STATE_B64 || process.env.BOOKING_STORAGE_STATE || '';
  if (!raw) return null;
  try {
    if (String(raw).trim().charAt(0) === '{') return JSON.parse(raw);
    return JSON.parse(Buffer.from(raw, 'base64').toString('utf8'));
  } catch (eState) { return null; }
}
